-- Ativa a tabela-rascunho (docs/fase2/regras-rascunho-v1.json). Gerado por docs/fase2/gerar-ativar-sql.mjs; não edite à mão.
-- Rodar no SQL Editor do Supabase, primeiro no banco de teste. Uma ativa por organização (índice regras_uma_ativa).
-- Aborta sem mudar nada se a organização não existir ou se esta mesma tabela já estiver ativa (rodar de novo é seguro).
do $ativar$
declare v_org uuid; v_regras jsonb := $tabela${"_status":"Tabela ativada a partir de docs/fase2/regras-rascunho-v1.json; o histórico das decisões está no _status desse arquivo.","moeda":"BRL","sinal_percentual":40,"prazo_max_dias":60,"arredondamento":10,"formatos":{"landing_page":{"nome":"Landing page","base":2900,"piso":1500,"prazo_dias":5,"paginas_incluidas":1,"inclui":["Uma página com até 7 seções","Celular primeiro","Botão de WhatsApp e formulário","SEO básico e medição","Publicação no domínio do cliente"]},"institucional":{"nome":"Site institucional","base":7900,"piso":4500,"prazo_dias":8,"paginas_incluidas":5,"inclui":["Até 5 páginas","Celular primeiro","WhatsApp, formulário e mapa","SEO básico e medição","Publicação no domínio do cliente"]},"loja_plataforma":{"nome":"Loja virtual (Nuvemshop ou Shopify)","base":8900,"piso":6500,"prazo_dias":8,"paginas_incluidas":5,"inclui":["Configuração da plataforma e tema próprio","Até 30 produtos cadastrados com dados e fotos do cliente","Pix e cartão pelo meio de pagamento da plataforma","Frete pela tabela da plataforma","Páginas de política e contato"]}},"adicionais":{"pagina_extra":{"nome":"Página extra","valor":350,"prazo_dias":0.5,"max":10,"prioridade":5},"visual_exclusivo":{"nome":"Visual exclusivo (desenhado do zero, sem modelo)","valor":3200,"prazo_dias":3,"max":1,"prioridade":8,"requer":["institucional"]},"textos":{"nome":"Textos escritos pela Beyon Zero (por página)","valor":350,"prazo_dias":0.25,"max":15,"prioridade":10},"imagens":{"nome":"Curadoria de imagens","valor":250,"prazo_dias":0.5,"max":1,"prioridade":20},"formulario_avancado":{"nome":"Formulário com etapas ou anexos","valor":300,"prazo_dias":0.5,"max":3,"prioridade":30},"agendamento":{"nome":"Agendamento online","valor":450,"prazo_dias":1,"max":1,"prioridade":25},"blog":{"nome":"Blog ou área de notícias","valor":900,"prazo_dias":2,"max":1,"prioridade":40},"catalogo":{"nome":"Catálogo de produtos (sem pagamento)","valor":1500,"prazo_dias":3,"max":1,"prioridade":45},"integracao":{"nome":"Integração (CRM, planilha, sistema)","valor":900,"prazo_dias":1,"max":3,"prioridade":35},"idioma":{"nome":"Idioma adicional","valor":800,"prazo_dias":2,"max":2,"prioridade":50},"produtos_lote_25":{"nome":"Mais 25 produtos cadastrados","valor":300,"prazo_dias":0.5,"max":20,"prioridade":15,"requer":["loja_plataforma"]},"pagamento_extra":{"nome":"Meio de pagamento extra na loja","valor":400,"prazo_dias":0.5,"max":2,"prioridade":20,"requer":["loja_plataforma"]},"frete_transportadora":{"nome":"Frete por transportadora (Melhor Envio, Frenet)","valor":500,"prazo_dias":1,"max":1,"prioridade":22,"requer":["loja_plataforma"]},"integracao_erp":{"nome":"Integração da loja com ERP ou nota fiscal (Bling, Tiny)","valor":1500,"prazo_dias":2,"max":2,"prioridade":35,"requer":["loja_plataforma"]},"marketplace":{"nome":"Integração com marketplace (Mercado Livre, Shopee)","valor":1200,"prazo_dias":1.5,"max":2,"prioridade":40,"requer":["loja_plataforma"]},"migracao_loja":{"nome":"Migração de outra loja","valor":1500,"prazo_dias":2,"max":1,"prioridade":30,"requer":["loja_plataforma"]},"interacao_leve":{"nome":"Animações de entrada e rolagem no site todo","valor":900,"prazo_dias":1,"max":1,"prioridade":36},"interacao_assinatura":{"nome":"Interação de assinatura (animação interativa única, como as do site da Beyon Zero)","valor":2500,"prazo_dias":2,"max":3,"prioridade":37},"atendente_ia_essencial":{"nome":"Atendente de IA no site, plano Essencial","valor":2400,"mensal":590,"em_preparo":true,"prazo_dias":3,"max":1,"prioridade":60},"atendente_ia_profissional":{"nome":"Atendente de IA no site, plano Profissional","valor":3900,"mensal":890,"em_preparo":true,"prazo_dias":3,"max":1,"prioridade":61},"atendente_ia_avancado":{"nome":"Atendente de IA no site, plano Avançado","valor":4900,"mensal":1390,"em_preparo":true,"prazo_dias":3,"max":1,"prioridade":62}},"multiplicadores":{"urgencia":{"fator":1.3,"prazo_fator":0.6,"descricao":"Entrega antes do prazo padrão"},"complexidade_alta":{"fator":1.25,"descricao":"Integrações ou regras de negócio fora do padrão"}},"descontos_autorizados":[],"limites":{"valor_max_automatico":10000000,"valor_max_projeto":10000000}}$tabela$::jsonb; n integer;
begin
  select id into v_org from app.organizacoes where slug = 'beyon-zero';
  if v_org is null then raise exception 'organização beyon-zero não existe neste banco'; end if;
  if exists (select 1 from app.regras_comerciais where org_id = v_org and status = 'ativa' and regras = v_regras) then
    raise exception 'esta tabela já está ativa: nada a fazer';
  end if;
  update app.regras_comerciais set status = 'arquivada' where org_id = v_org and status = 'ativa';
  insert into app.regras_comerciais (org_id, versao, status, regras, fontes, aprovada_em)
  select v_org, coalesce(max(versao), 0) + 1, 'ativa', v_regras, 'aprovada pelo dono em 2026-11-08 (chat): Confirmo, pode excluir o Atelier.', now() from app.regras_comerciais where org_id = v_org;
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'esperava gravar 1 tabela, gravou %', n; end if;
end
$ativar$;
-- conferir: select versao, status, regras -> 'formatos' ? 'sob_medida' as tem_atelier from app.regras_comerciais order by versao;
